          "correctAnswer": 3,
          "explanation": "<b>Dịch nghĩa:</b> Tôi trích dẫn nguyên văn bài viết trên báo vào bản báo cáo của mình.<br><b>Từ vựng:</b> 「引用」（いんよう）nghĩa là trích dẫn nguyên văn một đoạn văn, số liệu, ý kiến từ sách báo vào bài viết của mình.<br><i>Phân tích các phương án:</i><br>• 1. プレゼンが上手い先輩のやり方を...: Bắt chước/học hỏi cách làm của tiền bối phải dùng 「真似る・見習う」, không dùng 引用.<br>• 2. 大きな川から水を...: Dẫn nước từ sông lớn phải dùng 「引く・引水する」, không dùng 引用.<br>• 3. <b>レポートで、新聞記事を引用する: [Đúng]</b> Trích dẫn bài báo vào báo cáo là cách kết hợp từ hoàn toàn chuẩn xác.<br>• 4. ほかの人のお金を...: Dùng tiền của người khác phải dùng 「使い込む・盗む」, không dùng 引用."
