          "correctAnswer": 2,
          "explanation": "<b>Dịch nghĩa câu hỏi:</b> Vì sao khi nhận được một bức thư viết tay, con người ta lại cảm nhận được hơi ấm tình cảm?<br><b>Phân tích đoạn văn & Căn cứ chọn đáp án:</b><br>Đoạn 1 nêu rõ: 「手書きの文字には、書き手の呼吸や体温のようなものが宿っている。筆跡の勢い、インクのかすれ、選ばれた便箋や切手の一枚にいたるまで、相手のことを思い浮かべながら過ごした『時間』と『心』が刻み込まれているからだ」 (Bởi vì trong nét chữ viết tay có chứa đựng nhịp thở và hơi ấm của người viết, từ nét bút mạnh yếu, vết mực, đến lá thư và con tem đều in đậm 'thời gian' và 'tâm ý' mà người viết dành cho đối phương).<br><i>Phân tích các phương án:</i><br>• 1. 手紙を書くのに長い時間がかかったことが文章から分かるから: Biết được mất nhiều thời gian qua câu văn -> Chỉ nói về câu chữ chứ chưa đúng bản chất nét chữ và mực.<br>• 2. <b>筆跡やインクの濃淡などに書き手の個性や温かい感情が宿っているから: [Đúng]</b> Vì trong nét chữ và độ đậm nhạt của mực có gửi gắm cá tính và tình cảm ấm áp của người viết.<br>• 3. 美しい便箋や切手が高価で価値があると感じるから: Thấy phong bì và tem đắt tiền -> Sai, bài nói về tấm lòng chứ không phải tiền bạc.<br>• 4. 手書きの手紙は滅多に届かない珍しいものだから: Vì thư tay hiếm khi có -> Đây chỉ là bối cảnh thời đại, không phải lý do tạo nên hơi ấm.",
          "passage": "【本文 2：手書きの手紙とデジタル文字】\nパソコンやスマートフォンが普及した現代、手書きで文字を書く機会は激減した。連絡の多くはメールやSNSで瞬時に行われ、その利便性は計り知れない。しかし、年賀状やお礼状など、特別な機会に手書きの手紙を受け取ると、画面上の文字とは全く異なる温もりを感じることがある。\n手書きの文字には、筆跡の揺れやインクの濃淡、選ばれた便箋やペンの色など、書き手の感情や気遣いがそのまま表れる。整然と並んだフォント文字は情報を効率よく伝達するには最適だが、書き手の「心」そのものを届ける力においては、不完全で個性的な手書きの文字にかなわないのである。"
