          "passage": "【A】\n新しい語学を身につける際、文法規則を体系的に学ぶことが何よりも近道である。文法の骨組みがしっかりしていれば、未知の文章に出会っても論理的に意味を推測できるし、正確で誤解のない文章を作成できる。感覚だけに頼って単語を並べる学習法では、日常会話の域を出ることはできない。\n\n【B】\n外国語の習得で最も大切なのは、失敗を恐れずに声に出して使ってみることだ。文法の間違いを気にしすぎると、言葉が口から出なくなってしまう。幼児が文法を学ばずに母国語を話せるようになるように、実際のコミュニケーションの中で大量のインプットとアウトプットを繰り返すことこそが、自然な言語感覚を養う唯一の道である。"
