          "correctAnswer": 2,
          "explanation": "<b>Dịch nghĩa câu hỏi:</b> Ông Suzuki sống trong thành phố muốn tập hợp 150 người tham gia để tổ chức buổi giao lưu cộng đồng miễn phí vào buổi chiều (13:00〜17:00). Chi phí sử dụng hội trường là bao nhiêu?<br><b>Phân tích bảng biểu thông tin & Căn cứ chọn đáp án:</b><br>1. Quy mô người tham gia: 150 người -> Cần chọn <b>Trung hội trường (中ホール)</b> vì có sức chứa 200 người (Phòng họp A chỉ 30 người, Đại hội trường tới 500 người thừa thãi lãng phí).<br>2. Khung giờ thuê: Buổi chiều (13:00〜17:00) -> Giá thuê gốc của Trung hội trường buổi chiều là <b>12,000 yên</b>.<br>3. Điều kiện phụ thu: Ông Suzuki là 'cư dân trong thành phố' (市内在住) nên không bị tính phụ thu ngoài thành phố (市外者 +50%). Buổi giao lưu là 'miễn phí' (không thu tiền vé của người tham gia) nên không bị nhân đôi phí sử dụng (chỉ khi thu vé mới tính × 2.0).<br>-> Tổng chi phí đúng bằng giá niêm yết: <b>12,000 yên</b>.<br><i>Phân tích các phương án:</i><br>• 1. 8,000円: Giá của Trung hội trường vào buổi sáng (午前).<br>• 2. <b>12,000円: [Đúng]</b> Mức giá chuẩn xác cho Trung hội trường buổi chiều dành cho cư dân nội thành không thu phí vào cửa.<br>• 3. 18,000円: Giá nếu bị cộng thêm 50% dành cho người ngoài thành phố (12,000 × 1.5).<br>• 4. 20,000円: Giá của Đại hội trường buổi chiều.",
          "passage": "【市民ホール利用案内】\n・大ホール：定員500名（利用料：午前15,000円／午後20,000円／夜間25,000円／終日50,000円）\n・中ホール：定員200名（利用料：午前8,000円／午後12,000円／夜間15,000円／終日30,000円）\n・会議室A：定員30名（利用料：1時間1,500円）\n【注意事項】\n1. 市外在住者が利用する場合は、上記料金の5割増しとする。\n2. 入場料を徴収する営利目的のイベントは、利用料が2倍となる。\n3. キャンセル料：利用日の14日前までは無料、7日前までは半額、それ以降は全額。"
