          "mondai": 14,
          "mondaiName": "問題14: 情報検索",
          "type": "reading",
          "question": "【問い2】市外に住む田中さんは、中ホールで参加者から1人2,000円の入場料を受け取るピアノコンサートを夜間（18:00〜21:30）に開催する予定である。利用料の合計はいくらになるか。",
