          "correctAnswer": 3,
          "explanation": "<b>Dịch nghĩa câu hỏi:</b> Ông Tanaka sống ngoài thành phố dự định tổ chức một buổi hòa nhạc piano tại Trung hội trường (中ホール) vào ban đêm (18:00〜21:30) và có thu tiền vé vào cửa 2,000 yên/người. Tổng chi phí sử dụng hội trường là bao nhiêu?<br><b>Phân tích bảng biểu thông tin & Căn cứ chọn đáp án:</b><br>1. Hội trường và khung giờ: Trung hội trường vào ban đêm (夜間: 18:00〜21:30) có mức giá gốc niêm yết là <b>15,000 yên</b>.<br>2. Phụ thu người ngoài thành phố (市外利用): Mục quy định ghi rõ người sống ngoài thành phố phải trả thêm 50% mức phí cơ bản -> 15,000 × 1.5 = <b>22,500 yên</b>.<br>3. Phụ thu tổ chức có thu tiền vé (入場料徴収): Quy định ghi rõ nếu người tổ chức thu vé vào cửa từ người tham dự (mục đích kinh doanh/thương mại) thì phí sử dụng sẽ được nhân đôi (2倍) trên mức phí áp dụng -> 22,500 yên × 2 = <b>45,000 yên</b>.<br>-> Vậy tổng chi phí sử dụng hội trường là <b>45,000 yên</b>.<br><i>Phân tích các phương án:</i><br>• 1. 15,000円: Chỉ là mức giá gốc cơ bản cho cư dân trong thành phố và không thu phí vé.<br>• 2. 30,000円: Chưa tính khoản phụ thu 50% dành cho người ngoài thành phố (15,000 × 2).<br>• 3. <b>45,000円: [Đúng]</b> Tính đầy đủ cả hai khoản phụ thu: (15,000 × 1.5) × 2 = 45,000 yên.<br>• 4. 60,000円: Sai lệch do tính nhầm mức giá của hội trường khác.",
          "passage": "【市民ホール利用案内】\n・大ホール：定員500名（利用料：午前15,000円／午後20,000円／夜間25,000円／終日50,000円）\n・中ホール：定員200名（利用料：午前8,000円／午後12,000円／夜間15,000円／終日30,000円）\n・会議室A：定員30名（利用料：1時間1,500円）\n【注意事項】\n1. 市外在住者が利用する場合は、上記料金の5割増しとする。\n2. 入場料を徴収する営利目的のイベントは、利用料が2倍となる。\n3. キャンセル料：利用日の14日前までは無料、7日前までは半額、それ以降は全額。"
